responsePreview:
This Terraform configuration defines an AWS provider and looks up the latest Amazon Linux 2 AMI using the `aws_ami` data source. It filters for official Amazon-owned Amazon Linux 2 HVM AMIs using `gp2` storage and outputs the selected AMI ID and name.

```hcl
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to use for looking up the Amazon Linux 2 AMI."
  type        = string
  default     = "us-east-1"
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

output "amazon_linux_2_ami_id" {
  description = "The ID of the latest Amazon Linux 2 AMI."
  value       = data.aws_ami.latest_amazon_linux_2.id
}
